// ============================================================
// Arma el briefing de datos y el prompt para Claude.
// No inventa nada: todo lo que va al prompt sale de las APIs.
// ============================================================

function sacar(nodo) {
  try { return $(nodo).all().map(i => i.json); } catch (e) { return []; }
}

// --- Dolares de hoy ---
const dolaresRaw = sacar('Dólares de hoy');
const dolares = Array.isArray(dolaresRaw[0]) ? dolaresRaw[0] : dolaresRaw;
const casa = id => dolares.find(d => d && d.casa === id);

const blue = casa('blue');
const oficial = casa('oficial');
const mep = casa('bolsa');
const ccl = casa('contadoconliqui');

// --- Variacion semanal del blue ---
const semanaRaw = sacar('Blue hace una semana')[0];
const blueAntes = semanaRaw && semanaRaw.venta ? Number(semanaRaw.venta) : null;
const varBlue = (blue && blueAntes)
  ? ((blue.venta - blueAntes) / blueAntes * 100)
  : null;

// --- Brecha ---
const brecha = (blue && oficial)
  ? ((blue.venta - oficial.venta) / oficial.venta * 100)
  : null;

// --- Inflacion ---
const ipcRaw = sacar('Serie de inflación');
const ipc = Array.isArray(ipcRaw[0]) ? ipcRaw[0] : ipcRaw;
const ultInfl = ipc.length ? ipc[ipc.length - 1] : null;
const doce = ipc.slice(-12);
const acum12 = doce.length
  ? (doce.reduce((a, m) => a * (1 + m.valor / 100), 1) - 1) * 100
  : null;

// --- Riesgo pais ---
const rp = sacar('Riesgo país')[0];
const riesgo = rp && rp.valor ? rp.valor : null;

const n = v => v === null || v === undefined ? 'sin dato' : Number(v).toLocaleString('es-AR', { maximumFractionDigits: 1 });
const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const mesNombre = f => { const p = String(f).split('-'); return MESES[parseInt(p[1],10)-1] + ' de ' + p[0]; };

// --- Personajes del blog: rota uno por semana ---
const VOCES = [
  { nombre: 'el Analista de Datos', estilo: 'mira los numeros antes que las opiniones, ordena la semana con datos concretos y desconfia de las explicaciones de una sola causa' },
  { nombre: 'la Guardiana del Ahorro', estilo: 'traduce todo a lo que le pasa al ahorro de una persona comun, prioriza el habito sobre el timing' },
  { nombre: 'el Cazador de Mitos', estilo: 'agarra una frase que se repite mucho esta semana y la desarma con datos' },
  { nombre: 'el Domador de Tormentas', estilo: 'ubica lo de esta semana en el ciclo economico, con perspectiva historica y sin dramatismo' },
  { nombre: 'el Ciudadano', estilo: 'pregunta lo que preguntaria cualquiera y lo responde en criollo, sin jerga' }
];
const semanaDelAnio = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 1)) / 604800000);
const voz = VOCES[semanaDelAnio % VOCES.length];

// --- Briefing ---
const hoy = new Date().toLocaleDateString('es-AR', { day: 'numeric', month: 'long', year: 'numeric' });

const datos = [
  `Fecha: ${hoy}`,
  `Dolar blue: $${n(blue?.venta)} (venta)`,
  `Dolar oficial: $${n(oficial?.venta)} (venta)`,
  `Dolar MEP: $${n(mep?.venta)}`,
  `Dolar CCL: $${n(ccl?.venta)}`,
  `Brecha blue vs oficial: ${n(brecha)}%`,
  varBlue !== null
    ? `Variacion del blue en los ultimos 7 dias: ${varBlue >= 0 ? '+' : ''}${n(varBlue)}%`
    : 'Variacion semanal del blue: sin dato disponible',
  ultInfl ? `Ultima inflacion mensual publicada: ${n(ultInfl.valor)}% (${mesNombre(ultInfl.fecha)})` : 'Inflacion mensual: sin dato',
  acum12 !== null ? `Inflacion acumulada de los ultimos 12 meses: ${n(acum12)}%` : '',
  riesgo !== null ? `Riesgo pais: ${n(riesgo)} puntos basicos` : ''
].filter(Boolean).join('\n');

const system = `Sos ${voz.nombre}, uno de los personajes que escriben el blog de Obol Finance, una app argentina de educacion financiera gamificada.

Voz: ${voz.estilo}.

Reglas que no se negocian:
- Escribis en espanol rioplatense (vos, tenes, sabes). Tono conversacional y directo, sin solemnidad.
- Nunca das recomendaciones de inversion ni decis que comprar o vender. Explicas que significan los numeros.
- Usas UNICAMENTE los datos que te paso. Si un dato dice "sin dato", no lo mencionas y no lo estimas.
- No inventas cifras, fuentes, declaraciones ni hechos de actualidad. No tenes acceso a noticias: solo tenes estos numeros.
- Nada de clickbait, ni signos de exclamacion, ni frases como "en un mundo donde".
- Explicas el mecanismo detras del numero, que es lo que hace util a la nota.`;

const prompt = `Escribi la nota semanal del blog de Obol con estos datos:

${datos}

Estructura:
- Un titulo de menos de 70 caracteres, sin dos puntos si podes evitarlos.
- Una bajada de una sola oracion.
- Entre 350 y 450 palabras en 4 o 5 parrafos.
- Arranca por el dato que mas se movio esta semana, no por un resumen general.
- Al menos un parrafo tiene que explicar POR QUE pasa lo que pasa, en terminos que entienda alguien que recien empieza.
- Cerra conectando con algo practico que la persona pueda entender de su propia plata. Sin recomendar nada.

Respondes SOLO con un objeto JSON valido, sin backticks ni texto alrededor:
{"titulo": "...", "bajada": "...", "asunto": "asunto del mail, menos de 60 caracteres", "parrafos": ["parrafo 1", "parrafo 2", "..."]}`;

return [{ json: { system, prompt, datos, voz: voz.nombre, fecha: hoy } }];

// Toma la respuesta de Claude, la parsea y arma el HTML del borrador.
const r = $input.first().json;

const texto = (r.content || [])
  .filter(b => b.type === 'text')
  .map(b => b.text)
  .join('\n')
  .replace(/```json|```/g, '')
  .trim();

let nota;
try {
  nota = JSON.parse(texto);
} catch (e) {
  // Si no devolvio JSON limpio, no rompemos: mandamos el texto crudo para revisar a mano.
  nota = {
    titulo: 'Revisar: Claude no devolvio JSON',
    bajada: '',
    asunto: 'Newsletter Obol — revisar borrador',
    parrafos: [texto]
  };
}

const brief = $('Arma el briefing').first().json;
const parrafos = (nota.parrafos || []).map(p => `<p style="margin:0 0 16px">${p}</p>`).join('\n');

const html = `<div style="font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;max-width:560px;margin:0 auto;color:#12212E;line-height:1.65">
  <p style="font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:#B8862A;margin:0 0 14px">Obol Finance · La semana en números</p>
  <h1 style="font-family:Georgia,serif;font-size:26px;font-weight:600;line-height:1.25;margin:0 0 10px">${nota.titulo || ''}</h1>
  <p style="font-size:17px;color:#5B6B78;margin:0 0 24px">${nota.bajada || ''}</p>
  ${parrafos}
  <p style="font-size:13px;color:#5B6B78;margin:26px 0 0">Por ${brief.voz} · ${brief.fecha}</p>
  <hr style="border:none;border-top:1px solid #E5E0D6;margin:22px 0 14px">
  <p style="margin:0 0 14px"><a href="https://obolfinance.com.ar/dolar.html" style="color:#B8862A">Ver el dólar y la inflación actualizados →</a></p>
  <p style="font-size:12px;color:#8a8378;margin:0">Contenido educativo. No es asesoramiento financiero ni una recomendación de inversión.<br>Para darte de baja, respondé este mail con la palabra BAJA.</p>
</div>

<!-- ===== DATOS QUE USÓ CLAUDE (verificar antes de enviar) =====
${brief.datos}
-->`;

return [{ json: {
  asunto: nota.asunto || nota.titulo || 'Newsletter Obol',
  titulo: nota.titulo,
  html,
  datos: brief.datos,
  voz: brief.voz
} }];
